// The php backend (docs/spec/fsm.md, B-4 and B-6; docs/plans/fsm-v1.md, C-2): the generated files of the php package
// `src/` and the native test module `tests/Vectors.php`. It takes the IRs of the machines (normalize.mjs), in definition order,
// and the lock and the php namespace, and returns the text of every file; it writes nothing. The output is deterministic: declaration
// order, four spaces of indentation and a final line break. The core imports nothing from node:, and the generated code has no
// runtime dependency.
//
// A PHP file starts with `<?php`, so the fsm-gen header is its second line (write-generated.mjs reads it there). The
// namespace of a machine is <ns>\<Pascal machine key>: the states and events are backed enums, the functions of B-6 are
// namespace functions in functions.php, and the shared Fsm namespace holds the Code enum and the Error exception.
//
// The language-forced differences from the other kinds: `Error` extends \Exception, whose `$code` is protected and holds the
// string code, so the code is read with getCode(); its fields `expected`, `actual` and `event` are ints (the state codes and the
// event index), because one shared class cannot type the enums of every machine. `Code` and `Error` are separate files, since
// composer's PSR-4 loads one class per file. A PHP enum is closed, so a state argument that is no state is a TypeError of the
// call, and no E_UNKNOWN_CODE is raised for it. Only from_code takes a raw value: it is declared `mixed` and checked with is_int,
// because the strict_types of the generated file does not reach the calls of a caller without it (a coercion would give the
// state of "2" or 2.0, and true would give the state of 1). A value that is not an int is E_UNKNOWN_CODE in every caller.

import { forKind } from '../core/vectors.mjs';

const SHARED = 'fsm';
const KIND = 'php';
const NAMESPACE = /^[A-Za-z][A-Za-z0-9]*(\\[A-Za-z][A-Za-z0-9]*)*$/;

/** The member name of a key: the pascal notation of B-6. Keys match ^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$, so this is one-to-one. */
const pascal = key => key.split('_').map(word => word[0].toUpperCase() + word.slice(1)).join('');

/** The second line of a generated file, after `<?php` (docs/spec/fsm.md, B-6). */
const header = from => `// Code generated by fsm-gen from ${from}; DO NOT EDIT.`;

/** The text of a list of lines: each line ends with a line break. */
const text = lines => `${lines.join('\n')}\n`;

/** The opening lines of a file of namespace `ns`: the tag, the header, strict types and the namespace. */
const opening = (from, ns) => ['<?php', header(from), 'declare(strict_types=1);', '', `namespace ${ns};`, ''];

/** The php namespace of the generated files, which must be given; anything else is an Error, so nothing is written. */
function checkedNamespace(phpNamespace) {
  if (typeof phpNamespace !== 'string' || !NAMESPACE.test(phpNamespace)) {
    throw new Error(`php: the php namespace must be letters and digits separated by single backslashes, such as Polyspec\\FsmTest; it is ${JSON.stringify(phpNamespace)}`);
  }
  return phpNamespace;
}

/** The namespace of a machine module: <ns>\<Pascal machine key>. */
const moduleOf = (phpNamespace, machine) => `${phpNamespace}\\${pascal(machine)}`;

/** The string literal of a PHP single-quoted string. */
const literal = value => `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/** The state enum of `ir`: each case is a state with its code as the value. */
function stateFile(ir, ns) {
  const { machine, states } = ir;
  return text([
    ...opening(machine, ns),
    `/** The states of ${machine}: the value of each case is its code (docs/spec/fsm.md, B-6). */`,
    'enum State: int',
    '{',
    ...states.map(state => `    case ${pascal(state.key)} = ${state.code};`),
    '}',
  ]);
}

/** The event enum of `ir`: each case is an event with its declaration index from 1 as the value. */
function eventFile(ir, ns) {
  const { machine, events } = ir;
  return text([
    ...opening(machine, ns),
    `/** The events of ${machine}: the value of each case is its position in the declaration, from 1 (docs/spec/fsm.md, B-6). */`,
    'enum Event: int',
    '{',
    ...events.map((event, index) => `    case ${pascal(event.key)} = ${index + 1};`),
    '}',
  ]);
}

/** The result class of apply: the state the event leads to, and whether the stored state changed. */
function stepFile(ir, ns) {
  return text([
    ...opening(ir.machine, ns),
    '/** The result of apply: the state that the event leads to, and whether the stored state changed (docs/spec/fsm.md, B-6). */',
    'final class Step',
    '{',
    '    public function __construct(',
    '        public readonly State $to,',
    '        public readonly bool $changed,',
    '    ) {',
    '    }',
    '}',
  ]);
}

/** The namespace functions of `ir`: initial, code, key, fromCode, isFinal, eventsFrom, target and apply (docs/spec/fsm.md, B-6). */
function functionsFile(ir, ns, phpNamespace, reservedCodes) {
  const { machine, initial, states, events, transitions } = ir;
  const reserved = [...reservedCodes].sort((a, b) => a - b);
  const stateOf = key => `State::${pascal(key)}`;
  const eventOf = key => `Event::${pascal(key)}`;
  const outgoing = state => events.filter(event => transitions.some(item => item.state === state.key && item.event === event.key));
  const toOf = (state, event) => transitions.find(item => item.state === state && item.event === event).to;
  const invalid = `throw new Error(Code::InvalidTransition, ${literal(`${machine}: the event `)} . $event->value . ${literal(' has no edge from ')} . $expected->value, $expected->value, null, $event->value)`;
  const lines = [
    ...opening(machine, ns),
    `use ${phpNamespace}\\Fsm\\Code;`,
    `use ${phpNamespace}\\Fsm\\Error;`,
    '',
    `/** The initial state of ${machine}. */`,
    'function initial(): State',
    '{',
    `    return ${stateOf(initial)};`,
    '}',
    '',
    '/** The code of a state, which is its value. */',
    'function code(State $state): int',
    '{',
    '    return $state->value;',
    '}',
    '',
    '/** The key of a state. */',
    'function key(State $state): string',
    '{',
    '    return match ($state) {',
    ...states.map(state => `        ${stateOf(state.key)} => ${literal(state.key)},`),
    '    };',
    '}',
    '',
    '/**',
    ' * The state of a code: E_RESERVED_CODE for a reserved code, E_UNKNOWN_CODE for any other value and for a value that is not an',
    ' * int (docs/spec/fsm.md, B-6). The type is checked here, not by the signature, so every caller gets the same result.',
    ' */',
    'function fromCode(mixed $value): State',
    '{',
    '    if (!is_int($value)) {',
    `        throw new Error(Code::UnknownCode, ${literal(`${machine}: a value of type `)} . get_debug_type($value) . ${literal(` is not a state of ${machine}`)});`,
    '    }',
    '    return match ($value) {',
    ...states.map(state => `        ${state.code} => ${stateOf(state.key)},`),
    ...reserved.map(code => `        ${code} => throw new Error(Code::ReservedCode, ${literal(`${machine}: code ${code} is reserved and is no state of ${machine}`)}),`),
    `        default => throw new Error(Code::UnknownCode, ${literal(`${machine}: `)} . $value . ${literal(` is not a state of ${machine}`)}),`,
    '    };',
    '}',
    '',
    '/** Whether a state is final. */',
    'function isFinal(State $state): bool',
    '{',
    '    return match ($state) {',
    ...states.map(state => `        ${stateOf(state.key)} => ${state.final ? 'true' : 'false'},`),
    '    };',
    '}',
    '',
    '/**',
    ' * The events that have an edge from a state, in declaration order.',
    ' *',
    ' * @return list<Event>',
    ' */',
    'function eventsFrom(State $state): array',
    '{',
    '    return match ($state) {',
    ...states.map(state => {
      const list = outgoing(state).map(event => eventOf(event.key));
      return `        ${stateOf(state.key)} => [${list.join(', ')}],`;
    }),
    '    };',
    '}',
    '',
    '/** The state that an event leads to from the expected state; E_INVALID_TRANSITION when the event has no edge from it. */',
    'function target(State $expected, Event $event): State',
    '{',
    '    return match ($expected) {',
    ...states.map(state => {
      const edges = outgoing(state);
      if (edges.length === 0) return `        ${stateOf(state.key)} => ${invalid},`;
      return [
        `        ${stateOf(state.key)} => match ($event) {`,
        ...edges.map(edge => `            ${eventOf(edge.key)} => ${stateOf(toOf(state.key, edge.key))},`),
        `            default => ${invalid},`,
        '        },',
      ].join('\n');
    }),
    '    };',
    '}',
    '',
    '/** Applies an event that the observed state expected leads to, when the stored state is actual (docs/spec/fsm.md, B-4). */',
    'function apply(State $expected, Event $event, State $actual): Step',
    '{',
    '    $to = target($expected, $event);',
    '    if ($actual === $expected) {',
    '        return new Step($to, true);',
    '    }',
    '    if ($actual === $to) {',
    '        return new Step($to, false);',
    '    }',
    `    throw new Error(Code::Conflict, ${literal(`${machine}: the stored state `)} . $actual->value . ${literal(' is neither ')} . $expected->value . ${literal(' nor ')} . $to->value, $expected->value, $actual->value, $event->value);`,
    '}',
  ];
  return text(lines);
}

/** The code enum of the shared namespace: the error codes of B-4, B-5 and B-6 without the E_ prefix in the case names. */
function codeFile(ns) {
  return text([
    ...opening(SHARED, ns),
    '/** The error codes that the functions of every machine throw; the value is the code of docs/spec/fsm.md, B-4 and B-6. */',
    'enum Code: string',
    '{',
    "    case Conflict = 'E_CONFLICT';",
    "    case InvalidTransition = 'E_INVALID_TRANSITION';",
    "    case UnknownCode = 'E_UNKNOWN_CODE';",
    "    case ReservedCode = 'E_RESERVED_CODE';",
    '}',
  ]);
}

/** The error of a machine function: getCode() is the value of the Code case; the fields hold the arguments that failed. */
function errorFile(ns) {
  return text([
    ...opening(SHARED, ns),
    '/**',
    ' * The error of a machine function (docs/spec/fsm.md, B-4 and B-6). getCode() is the value of the Code case, such as',
    ' * E_CONFLICT. The fields hold the arguments of apply or target that failed: the state codes and the event index; the others',
    ' * are null.',
    ' */',
    'final class Error extends \\Exception',
    '{',
    '    public function __construct(',
    '        Code $code,',
    '        string $message,',
    '        public readonly ?int $expected = null,',
    '        public readonly ?int $actual = null,',
    '        public readonly ?int $event = null,',
    '    ) {',
    '        parent::__construct($message);',
    '        $this->code = $code->value;',
    '    }',
    '}',
  ]);
}

/** The PHP int literal of a decimal string of the oracle; a value that is no decimal string is an Error. */
function integerOf(item) {
  if (typeof item !== 'string' || !/^-?[0-9]+$/.test(item)) throw new Error(`php: the input ${JSON.stringify(item)} is not a decimal string`);
  return item;
}

/**
 * The PHP literal of a typed input of the oracle (input_type: string, bool or float; docs/spec/fsm.md, B-6). An input without a
 * type is a decimal string written as an int (integerOf).
 */
function inputOf(text, type) {
  if (type === undefined) return integerOf(text);
  if (type === 'string') return literal(text);
  if (type === 'bool' && (text === 'true' || text === 'false')) return text;
  if (type === 'float' && /^-?[0-9]+\.[0-9]+$/.test(text)) return text;
  throw new Error(`php: the input ${JSON.stringify(text)} of type ${JSON.stringify(type)} is not a string, bool or float literal`);
}

/** A PHP literal of a vector value (null, bool, int, string, list or map) at nesting `depth`, with four spaces per level. */

function value(item, depth) {
  const pad = '    '.repeat(depth);
  if (item === null) return 'null';
  if (typeof item === 'boolean') return item ? 'true' : 'false';
  if (typeof item === 'number') {
    if (!Number.isSafeInteger(item)) throw new Error(`php: the vector value ${item} is not an integer`);
    return String(item);
  }
  if (typeof item === 'string') return literal(item);
  // The input_type of a case is read by its input and is not written (docs/spec/fsm.md, B-6).
  const entries = Array.isArray(item) ? item.map(entry => [undefined, entry]) : Object.entries(item).filter(([key]) => key !== 'input_type');
  if (entries.length === 0) return '[]';
  // An input is a decimal string of the oracle, written as the PHP int it names: the 64-bit range stays exact (docs/spec/fsm.md, B-6).
  const rendered = (key, entry) => (key === 'input' ? inputOf(entry, item.input_type) : value(entry, depth + 1));
  const cell = ([key, entry]) => `${pad}    ${key === undefined ? '' : `${literal(key)} => `}${rendered(key, entry)},`;
  return ['[', ...entries.map(cell), `${pad}]`].join('\n');
}

/**
 * The loader src/functions.php: composer's autoload.files names this one file, because PSR-4 cannot load functions. It requires
 * the functions.php of every machine in definition order, so a new machine needs no edit of composer.json.
 */
function loaderFile(irs) {
  return text([
    '<?php',
    header(SHARED),
    'declare(strict_types=1);',
    '',
    ...irs.map(ir => `require_once __DIR__ . '/${pascal(ir.machine)}/functions.php';`),
  ]);
}

/**
 * The files of the php package `src/` for the machines `irs` (their IRs in definition order), the lock and the options
 * { phpNamespace }: <Pascal>/State.php, Event.php, Step.php and functions.php per machine, then Fsm/Code.php and
 * Fsm/Error.php, and the loader functions.php. Each file is { path, content }.
 */
export function files(irs, lock, { phpNamespace } = {}) {
  const phpNs = checkedNamespace(phpNamespace);
  const out = [];
  for (const ir of irs) {
    if (!Object.hasOwn(lock, ir.machine)) throw new Error(`php: the lock has no entry for machine ${ir.machine}`);
    const ns = moduleOf(phpNs, ir.machine);
    const dir = pascal(ir.machine);
    out.push({ path: `${dir}/State.php`, content: stateFile(ir, ns) });
    out.push({ path: `${dir}/Event.php`, content: eventFile(ir, ns) });
    out.push({ path: `${dir}/Step.php`, content: stepFile(ir, ns) });
    out.push({ path: `${dir}/functions.php`, content: functionsFile(ir, ns, phpNs, lock[ir.machine].reserved) });
  }
  out.push({ path: 'Fsm/Code.php', content: codeFile(`${phpNs}\\Fsm`) });
  out.push({ path: 'Fsm/Error.php', content: errorFile(`${phpNs}\\Fsm`) });
  out.push({ path: 'functions.php', content: loaderFile(irs) });
  return out;
}

/**
 * The native test module tests/Vectors.php of `vectorList`, the vectors of every machine in order, in the namespace <ns>\Tests:
 * the class Vectors whose cases() returns each case under its test name test_<feature>__<id> (docs/plans/fsm-v1.md, C-4).
 */
export function vectorsFile(list, { phpNamespace } = {}) {
  const phpNs = checkedNamespace(phpNamespace);
  const cases = forKind(list, KIND).flatMap(({ machine, cases: items }) => items.map(item => [`test_${item.feature}__${item.id}`, { machine, case: item }]));
  const entries = cases.map(([name, data]) => `            ${literal(name)} => ${value(data, 3)},`);
  return text([
    ...opening(SHARED, `${phpNs}\\Tests`),
    '/** The vector cases of every machine, each under its test name (docs/plans/fsm-v1.md, C-4). */',
    'final class Vectors',
    '{',
    '    /** @return array<string, array{machine: string, case: array<string, mixed>}> */',
    '    public static function cases(): array',
    '    {',
    '        return [',
    ...entries,
    '        ];',
    '    }',
    '}',
  ]);
}
